#!/usr/bin/env bash
set -euo pipefail

: "${ALMAGEST_E2E_TIMEOUT:=45}"
source /e2e/lib/common.sh
# Generated by setup.sh.
# shellcheck disable=SC1091
source ./wireguard.env

kernel_if="wgk0"
target_body="Linux kernel WireGuard compatibility"
target_log="$E2E_RUNTIME/kernel-http.log"
http_pid=""

cleanup() {
	stop_static_http_target "$http_pid"
	ip link del "$kernel_if" 2>/dev/null || true
	stop_daemon
}

configure_kernel_peer() {
	local psk_file="$1"
	wg set "$kernel_if" \
		peer "$ALMAGEST_PUBLIC" \
		preshared-key "$psk_file" \
		allowed-ips 10.205.10.1/32 \
		endpoint 127.0.0.1:51860 \
		persistent-keepalive 1
}

kernel_ping_works() {
	ping -I "$kernel_if" -c 1 -W 2 10.205.10.1 >/dev/null 2>&1
}

kernel_ping_fails() {
	! kernel_ping_works
}

client_result_works() {
	local node="$1"
	local menu="$E2E_RUNTIME/http-menu.json"
	cli graph menu --node "$node" >"$menu"
	local status
	status="$(jq -er '.blocks[] | select(.id == "result") | .items[] | select(.id == "status") | .text' "$menu")"
	if [[ "$status" == "Status: 200 OK" ]]; then
		jq -e --arg body "$target_body" '
			.blocks[] | select(.id == "result") | .items[]
			| select(.id == "response" and .value == $body)
		' "$menu" >/dev/null
		return
	fi
	if [[ "$status" != "Status: running..." ]]; then
		cli graph click-menu-button --node "$node" --block request --button send >/dev/null
	fi
	return 1
}

peer_preshared_key_secret() {
	cli graph menu --node "$wg_node" | jq -er '
		.blocks[]
		| select(.id == "peers")
		| .items[]
		| select(.id == "peers")
		| .elements[]
		| select(.id == "kernel-peer")
		| .items[]
		| select(.id == "presharedKeySecret")
		| .value
	'
}

trap cleanup EXIT
if ! ip link add "$kernel_if" type wireguard 2>"$E2E_RUNTIME/kernel-wireguard.err"; then
	cat "$E2E_RUNTIME/kernel-wireguard.err" >&2
	fail "kernel WireGuard is unavailable"
fi
ip addr add 10.205.20.1/32 dev "$kernel_if"
wg set "$kernel_if" private-key kernel-private.key listen-port 51861
configure_kernel_peer preshared.key
ip link set dev "$kernel_if" mtu 1420 up
ip route replace 10.205.10.1/32 dev "$kernel_if"

http_pid="$(start_static_http_target 10.205.20.1 18083 "$target_body" "$target_log")"
start_daemon
trap cleanup EXIT

wait_graph_node "WireGuard Kernel Compat" || fail "WireGuard node missing"
wait_graph_node "VTun Kernel Compat" || fail "VTun node missing"
wait_graph_node "HTTP Kernel Compat" || fail "HTTP client node missing"
wg_node="$(node_id_by_name "WireGuard Kernel Compat")"
vtun_node="$(node_id_by_name "VTun Kernel Compat")"
http_client="$(node_id_by_name "HTTP Kernel Compat")"
wait_node_label "$wg_node" up || fail "WireGuard node did not become up"
wait_node_label "$vtun_node" wg-kernel-compat || fail "VTun node did not become ready"

retry "$ALMAGEST_E2E_TIMEOUT" "kernel-to-Almagest ICMP" kernel_ping_works \
	|| fail "kernel peer could not ping the Almagest VTun"
retry "$ALMAGEST_E2E_TIMEOUT" "Almagest-to-kernel HTTP" client_result_works "$http_client" \
	|| fail "Almagest HTTP client could not reach the kernel peer"

rotated_psk="$(wg genpsk)"
printf '%s\n' "$rotated_psk" >rotated-preshared.key
chmod 600 rotated-preshared.key
psk_secret="$(peer_preshared_key_secret)"
[[ -n "$psk_secret" ]] || fail "WireGuard did not migrate the initial preshared key to a secret"
cli secrets set --key "$psk_secret" --value "$rotated_psk" >/dev/null
# Secret mutations notify nodes synchronously, but WireGuard applies the new
# device configuration on its runtime worker. Wait for that public convergence
# barrier before the old-key peer can start another valid session.
wait_node_label "$wg_node" up \
	|| fail "WireGuard did not apply the rotated preshared key"
# Remove the kernel peer's established session. Its next handshake still uses
# the old key and must fail until the kernel configuration is updated.
wg set "$kernel_if" peer "$ALMAGEST_PUBLIC" remove
configure_kernel_peer preshared.key
retry 12 "preshared-key mismatch blocks traffic" kernel_ping_fails \
	|| fail "traffic did not stop after one-sided preshared-key rotation"

configure_kernel_peer rotated-preshared.key
retry "$ALMAGEST_E2E_TIMEOUT" "traffic after preshared-key rotation" kernel_ping_works \
	|| fail "traffic did not recover after both peers received the rotated key"

wg set "$kernel_if" peer "$ALMAGEST_PUBLIC" remove
retry 12 "removed kernel peer blocks traffic" kernel_ping_fails \
	|| fail "traffic did not stop after kernel peer removal"
configure_kernel_peer rotated-preshared.key
retry "$ALMAGEST_E2E_TIMEOUT" "traffic after kernel peer restoration" kernel_ping_works \
	|| fail "traffic did not recover after kernel peer restoration"

grep -F "GET /kernel" "$target_log" >/dev/null \
	|| fail "kernel HTTP target did not receive tunneled request"
wg show "$kernel_if" latest-handshakes | grep -F "$ALMAGEST_PUBLIC" >/dev/null \
	|| fail "wg did not report the Almagest peer handshake"

log "case passed"
